require "rails_helper"

RSpec.describe TimekeepingSnapshots do
  it "replaces a default with a symbol-keyed override instead of adding a second key" do
    entry_fields = TimekeepingContract.load(:entry_snapshots).fetch("entry_fields")

    entry = described_class.entry(id: 11, company_id: 3, version: 2, project_id: 5, user_id: 7,
                                  review_status: "approved", source: "cli")

    # A symbol key left beside the string default would send a payload with a key the contract does not list.
    expect(entry.keys).to match_array(entry_fields)
    expect(entry.values_at("review_status", "source")).to eq(["approved", "cli"])
  end
end

require "rails_helper"

RSpec.describe TimekeepingSnapshots do
  it "does not leak a change to one built entry's metadata into the next entry" do
    first = described_class.entry(id: 1, company_id: 2, version: 1, project_id: 3, user_id: 4)
    first["source_metadata"]["token"] = "secret"
    first["proof_metadata"]["url"] = "https://example.test"

    # Every spec shares the builder, so a default hash reused between calls would let one example
    # change the payload another example sends.
    second = described_class.entry(id: 1, company_id: 2, version: 2, project_id: 3, user_id: 4)

    expect(second.values_at("source_metadata", "proof_metadata")).to eq([{}, {}])
  end
end

require "rails_helper"

RSpec.describe TimekeepingSnapshots do
  it "defaults outbox_position to the entry's own version, including an overridden one" do
    entry = described_class.entry(id: 1, company_id: 2, version: 3, project_id: 4, user_id: 5)

    item = described_class.item(entry, generation: 7)
    explicit = described_class.item(entry, generation: 7, outbox_position: 10)

    expect(item).to eq("generation" => 7, "outbox_position" => 3, "entry" => entry)
    expect(explicit.fetch("outbox_position")).to eq(10)
  end
end

require "rails_helper"

RSpec.describe TimekeepingSnapshots do
  it "keeps a repeated entry and out-of-order items exactly as given in the batch" do
    contract = TimekeepingContract.load(:entry_snapshots)
    newer = described_class.item(described_class.entry(id: 1, company_id: 2, version: 2, project_id: 3, user_id: 4),
                                 generation: 1, outbox_position: 9)
    older = described_class.item(described_class.entry(id: 1, company_id: 2, version: 1, project_id: 3, user_id: 4),
                                 generation: 1, outbox_position: 4)

    # Specs build re-sends and unsorted batches on purpose to test the consumer, so the wrapper
    # must neither drop a duplicate nor reorder items.
    batch = described_class.batch(newer, older, newer)

    expect(batch).to eq("schema_version" => contract.fetch("schema_version"), "snapshots" => [newer, older, newer])
  end
end

