RSpec.describe TimekeepingSnapshots do
  include TimekeepingContractExampleHelpers

  it "snapshot_item maps its arguments onto the shared builder's ids without swapping any" do
    # Every argument is distinct and explicit, so no timekeeping_arrange default runs and a
    # swapped id (company for project, user for entry) changes the result.
    item = snapshot_item(entry_id: 101, company: 202, version: 3, generation: 4, project: 505, user: 606, note: "moved")

    expected = described_class.item(
      described_class.entry(id: 101, company_id: 202, version: 3, project_id: 505, user_id: 606, note: "moved"),
      generation: 4, outbox_position: 3
