require "rails_helper"
require_relative "contract_example_helpers"

RSpec.describe TimekeepingContractExampleHelpers do
  include TimekeepingContractExampleHelpers

  # "Moving the snapshot builder into one shared helper touches some 13 spec files and changes no behaviour, so I am leaving it for its own change."
  # Explicit generation, project and user keep the timekeeping_arrange defaults from being evaluated.
  it "snapshot_item still returns the exact item it built before delegating, with every default and override in place" do
    item = snapshot_item(entry_id: 80_001, company: 2, version: 3, generation: 4, project: 5, user: 6,
                         discarded_at: "2026-03-03T10:00:00Z")

    expected_entry = TimekeepingContract.load(:entry_snapshots).fetch("entry_fields").index_with(nil).merge(
      "id" => 80_001, "company_id" => 2, "version" => 3, "project_id" => 5, "user_id" => 6,
      "work_date" => "2026-03-02", "duration" => 90.0, "note" => "v3", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "proof_metadata" => {}, "created_at" => "2026-03-02T09:00:00Z", "updated_at" => "2026-03-02T09:00:00Z",
      "discarded_at" => "2026-03-03T10:00:00Z"
    )
    expect(item).to eq("generation" => 4, "outbox_position" => 3, "entry" => expected_entry)
  end
end
